CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.developer_packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(name) BETWEEN 2 AND 100), description text NOT NULL CHECK (length(description) BETWEEN 10 AND 2000), features text[] NOT NULL DEFAULT '{}', price numeric(12,2) NOT NULL CHECK (price > 0), currency text NOT NULL DEFAULT 'RWF' CHECK (currency IN ('RWF','USD')), published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.developer_packages TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.developer_packages TO authenticated;
GRANT ALL ON public.developer_packages TO service_role;
ALTER TABLE public.developer_packages ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_packages ON public.developer_packages FOR SELECT TO anon, authenticated USING (published);
CREATE POLICY admin_packages ON public.developer_packages FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
GRANT SELECT ON public.portfolio_inquiries TO authenticated;
CREATE POLICY admin_inquiries ON public.portfolio_inquiries FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
ALTER TABLE public.portfolio_inquiries ADD COLUMN package_id uuid REFERENCES public.developer_packages(id), ADD COLUMN package_name text NOT NULL DEFAULT '';
